  const nn = n => String(n).padStart(2, '0');
  let lang = 'de';
  const raw = k => (DICT[lang] && DICT[lang][k]) || DICT.de[k] || '';
  const t = (k, n) => dec(n === undefined ? raw(k) : raw(k).replace('{n}', n));

  // ---------- language ----------
  const applyLang = l => {
    lang = LANGS.includes(l) ? l : 'de';
    html.setAttribute('lang', lang);
    d.querySelectorAll('[data-i18n]').forEach(el => {
      const v = raw(el.dataset.i18n);
      if (!v) return;
      if (el.tagName === 'TITLE') el.textContent = dec(v);
      else if (el.hasAttribute('data-i18n-html') && el.dataset.i18n === 'home.h1') {
        el.innerHTML = `<span class="h1-l">${raw('home.h1.line1')}</span> <span class="h1-l">${raw('home.h1.line2')}</span>`;
      } else el.innerHTML = v;
    });
    d.querySelectorAll('[data-i18n-attr]').forEach(el => el.dataset.i18nAttr.split(';').forEach(pair => {
      const [attr, k] = pair.split(':'); const v = raw(k); if (v) el.setAttribute(attr, dec(v));
    }));
    d.querySelectorAll('.lang-b').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.lang === lang)));
    d.querySelectorAll('[data-en-only]').forEach(el => { el.hidden = lang !== 'en'; });
    d.querySelectorAll('a[href]').forEach(a => {
      const h = a.getAttribute('href');
      if (!/^[a-z-]+\.html(#.*)?$/.test(h.replace(/\?lang=\w+/, ''))) return;
      const [path, hash] = h.replace(/\?lang=\w+/, '').split('#');
      a.setAttribute('href', path + (lang === 'en' ? '?lang=en' : '') + (hash ? '#' + hash : ''));
    });
    renderCount(); plateTitle();
  };
  const setLang = l => { applyLang(l); try { localStorage.setItem('cc-lang', lang); } catch (e) {} };

  // ---------- menu ----------
  const menuB = d.querySelector('.menu-b'), menu = d.getElementById('menu');
  if (menuB && menu) {
    const set = open => {
      menuB.setAttribute('aria-expanded', String(open)); menu.classList.toggle('open', open);
      menuB.querySelector('.menu-l').textContent = t(open ? 'header.menu.close' : 'header.menu.open');
      d.body.style.overflow = open ? 'hidden' : '';
    };
    menuB.addEventListener('click', () => set(menuB.getAttribute('aria-expanded') !== 'true'));
    d.addEventListener('keydown', e => { if (e.key === 'Escape' && menu.classList.contains('open')) { set(false); menuB.focus(); } });
    menu.querySelectorAll('.lang-b').forEach(b => b.addEventListener('click', () => { if (b.dataset.lang !== lang) setLang(b.dataset.lang); }));
  }

  // ---------- spread: photos, plate, rail, toc ----------
  const verso = d.querySelector('.verso'), recto = d.querySelector('.recto');
  const figs = [...d.querySelectorAll('.ph')];
  const chaps = [...d.querySelectorAll('.chap')];
