  const preload = id => { const f = figs.find(x => x.dataset.photo === id); if (f) load(f); };
  const setDigits = n => { const s = nn(n); reels.forEach((r, i) => r.style.setProperty('--d', s[i])); if (plateLive) plateLive.textContent = s; };
